export default "357\n{\"version\":0,\"id\":\"e4802d8799339d9ee4c8607b659a6d2130d6a4d37fbbd0b359ef6bc74855fef2\",\"main\":\"/core/push.gen.js\",\"imports\":{},\"resolutions\":{\"/core/push.gen.js\":{\"#package\":\"/package.json\"},\"/package.json\":{}},\"addons\":[],\"assets\":[],\"files\":{\"/core/push.gen.js\":{\"offset\":0,\"length\":271,\"mode\":420},\"/package.json\":{\"offset\":271,\"length\":954,\"mode\":420}}}\n// core/push.ts\nconsole.log(\"Hello Android notifications!\");\nBareKit.on(\"push\", (payload, reply) => {\n  console.log(\"Notification received:\", JSON.parse(payload));\n  reply(null, JSON.stringify({\n    title: \"Notification received\",\n    body: \"This is the body\"\n  }));\n});\n{\n  \"private\": true,\n  \"name\": \"bare-android\",\n  \"version\": \"1.0.0\",\n  \"type\": \"module\",\n  \"description\": \"Example of embedding Bare in an Android application\",\n  \"scripts\": {\n    \"lint\": \"prettier . --check\",\n    \"dev\": \"vite\",\n    \"bare:dev\": \"npm run build:bare && bare core/app.gen.js\",\n    \"build\": \"vite build\",\n    \"build:bare\": \"bun build --packages=external core/app.ts --outfile=core/app.gen.js && bun build --packages=external core/push.ts --outfile=core/push.gen.js\"\n  },\n  \"devDependencies\": {\n    \"@playwright/test\": \"^1.58.2\",\n    \"@types/node\": \"^25.5.0\",\n    \"bare\": \"^1.28.0\",\n    \"bare-link\": \"^1.2.0\",\n    \"bare-pack\": \"^1.3.0\",\n    \"bare-ws\": \"^2.1.0\",\n    \"prettier\": \"^3.4.2\",\n    \"prettier-config-holepunch\": \"^2.0.0\",\n    \"vite\": \"^6.0.0\"\n  },\n  \"dependencies\": {\n    \"bare-buffer\": \"^3.6.0\",\n    \"bare-env\": \"^3.0.0\",\n    \"bare-fs\": \"^4.5.5\",\n    \"bare-sidecar\": \"^0.3.0\",\n    \"hyperswarm\": \"^4.17.0\",\n    \"ws\": \"^8.19.0\"\n  }\n}\n"
